package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TokenBuffer.writeNumber(double d)
 */
public class TokenBuffer_writeNumber_TriageGen2Test {

    private ObjectMapper mapper;
    private TokenBuffer tokenBuffer;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        // Use a standard codec to initialize the buffer
        tokenBuffer = new TokenBuffer(mapper);
    }

    @Test
    public void testWriteNumber_PositiveDouble() throws IOException {
        double value = 123.45;
        tokenBuffer.writeNumber(value);

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, tokenBuffer.firstToken());

        // To verify the content, we serialize to a generator or check via parser
        // Since TokenBuffer is a buffer of tokens, we can use a parser to read it back
        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(value, parser.getDoubleValue(), 0.0001);
    }

    @Test
    public void testWriteNumber_NegativeDouble() throws IOException {
        double value = -456.78;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(value, parser.getDoubleValue(), 0.0001);
    }

    @Test
    public void testWriteNumber_Zero() throws IOException {
        double value = 0.0;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(value, parser.getDoubleValue(), 0.0);
    }

    @Test
    public void testWriteNumber_IntegerAsDouble() throws IOException {
        // Even if it's an integer value, the method signature is double
        double value = 100.0;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        // Depending on Jackson implementation, it might be VALUE_NUMBER_FLOAT or VALUE_NUMBER_INT
        // but usually writeNumber(double) results in a float token
        JsonToken token = parser.nextToken();
        if (token == JsonToken.VALUE_NUMBER_FLOAT) {
            assertEquals(value, parser.getDoubleValue(), 0.0);
        } else {
            assertEquals(value, parser.getDoubleValue(), 0.0);
        }
    }

    @Test
    public void testWriteNumber_Infinity() throws IOException {
        double value = Double.POSITIVE_INFINITY;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(Double.POSITIVE_INFINITY, parser.getDoubleValue(), 0.0);
    }

    @Test
    public void testWriteNumber_NaN() throws IOException {
        double value = Double.NaN;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        // NaN is typically handled as a float token
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(Double.NaN, parser.getDoubleValue());
    }

    @Test
    public void testWriteNumber_VerySmallDouble() throws IOException {
        double value = 1.23e-10;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(value, parser.getDoubleValue(), 0.0);
    }

    @Test
    public void testWriteNumber_VeryLargeDouble() throws IOException {
        double value = 1.23e10;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(value, parser.getDoubleValue(), 0.0);
    }
}
